import Mark, { type MarkType } from '@/components/Mark';

const TYPES: Record<string, MarkType> = { u: 'underline', h: 'highlight', c: 'circle' };

// Turns "Choose where you [[u|work]] from." into text with a hand-drawn mark on "work".
// u = underline, h = highlighter swipe, c = circle. Plain strings pass through unchanged.
export function renderMarks(text: string): React.ReactNode {
  const parts = text.split(/(\[\[[uhc]\|.+?\]\])/g);
  return parts.map((part, i) => {
    const m = part.match(/^\[\[([uhc])\|(.+?)\]\]$/);
    if (!m) return part;
    return (
      <Mark key={i} type={TYPES[m[1]]}>
        {m[2]}
      </Mark>
    );
  });
}
